#include <iostream>
#include <vector>
int main() {
    std::vector<std::vector<int>> m(3, std::vector<int>(4));
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 4; c++) {
            m[r][c] = r * 4 + c;
        }
    }
    int last = m[2][3];
    std::cout << "last=" << last << "\n"; // CHECK
    return 0;
}
